import datetime,hashlib,json
from pathlib import Path
original=Path('survey/out/polarity-sessions.jsonl');old={}
for line in original.open():
 row=json.loads(line);old[(row['arm'],row['seed'])]=row
assert len(old)==4272
new={}
for line in Path('survey/out/polarity-telemetry-sessions.jsonl').open():
 if not line.endswith('\n'):continue
 row=json.loads(line);key=(row['arm'],row['seed'])
 if key in old:new[key]=row
mismatch=[]
for key,row in new.items():
 if {k:v for k,v in row.items() if k!='stock_diagnostics'}!=old[key]:mismatch.append(key)
def canonical_digest(mapping):
 digest=hashlib.sha256()
 for key in sorted(mapping):
  row={k:v for k,v in mapping[key].items() if k!='stock_diagnostics'}
  digest.update(json.dumps(row,sort_keys=True,separators=(',',':'),allow_nan=False).encode()+b'\n')
 return digest.hexdigest()
result={'checked_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'original_records':4272,'matched_same_seed_records':len(new),'missing_original_keys':len(set(old)-set(new)),'mismatched_outcome_or_provenance_keys':mismatch,'comparison':'Every complete outer record field except newly added stock_diagnostics; includes exact unchanged complete Outcome, config, manifest hash, arm and seed','original_sessions_sha256':hashlib.sha256(original.read_bytes()).hexdigest(),'amended_sessions_sha256':hashlib.sha256(Path('survey/out/polarity-telemetry-sessions.jsonl').read_bytes()).hexdigest(),'original_preexisting_fields_canonical_sha256':canonical_digest(old),'amended_matched_preexisting_fields_canonical_sha256':canonical_digest(new),'canonical_digest_method':'sort by (arm, seed); omit only stock_diagnostics; JSON sort_keys=True, separators=(comma,colon), allow_nan=False; UTF-8 plus LF per row; SHA256 in that order','command':'python3 survey/out/polarity-telemetry-compare-original.py','comparison_script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'comparison_script_source':Path(__file__).read_text()}
Path('survey/out/polarity-telemetry-outcome-equivalence.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n');print(json.dumps({k:v for k,v in result.items() if k!='comparison_script_source'},indent=2));assert not mismatch;assert result['original_preexisting_fields_canonical_sha256']==result['amended_matched_preexisting_fields_canonical_sha256']
